    stat_free_v: "Free",
    stat_free_l: "Forever · no signup",
    disclaimer_eyebrow: "Good-faith estimate — not a binding determination",
    disclaimer_body: "Final duty is assessed by the destination customs authority at time of clearance and may differ based on inspection, valuation method, or origin documentation. Our numbers aim to be close to what you'll actually pay — but this is not legal or customs advice. For shipments above $25,000 or regulated goods, consult a licensed customs broker.",
    faq_eyebrow: "Questions we get weekly",
    duty_faq_1_q: "Where do your duty rates come from?",
    duty_faq_1_a: "Directly from each country's published tariff schedule — the US HTSUS, the EU TARIC database, the UK Integrated Online Tariff, Canada's CBSA tariff, and equivalents for all other markets. We do not scrape carrier quote engines.",
    duty_faq_2_q: "How often is the data updated?",
    duty_faq_2_a: "Weekly. Major tariff changes (e.g. new US/EU sanctions) are pulled through out-of-band, but the normal cadence is a weekly refresh from each authority's published feed.",
    duty_faq_3_q: "Does the calculator account for trade agreements?",
    duty_faq_3_a: "For the major agreements (USMCA, EU-UK TCA, CPTPP, Mercosur) we apply the preferential rate in the country profile where your origin qualifies. Rule-of-origin documentation is your responsibility — we do not generate certificates of origin.",
    duty_faq_4_q: "What if the customs authority charges something different than your estimate?",
    duty_faq_4_a: "Final assessment is always the customs authority's call. Our number is a good-faith estimate based on the published tariff schedule. Differences most often come from valuation method, HS classification disputes, or unexpected regulatory findings (licensing, restricted goods). For shipments above $25,000 or regulated categories, please use a licensed broker.",
    duty_faq_5_q: "Do you handle regulated goods?",
    duty_faq_5_a: "We flag general restrictions for lithium batteries, cosmetics, alcohol, pharmaceuticals and other regulated categories in the country profiles. Actual licensing and permits are handled outside the calculator — typically through a destination-country customs broker.",
    duty_faq_6_q: "Is the calculator really free?",
    duty_faq_6_a: "Yes. No signup, no paywall, no rate-limit on lookups. We're a small team in Hungary (Global Supply KFT) and the calculator will stay free.",
    duty_cta_pre: "Your customers shouldn't learn about customs at their",
