    privacy_s1_title: "1. Аналитика и отслеживание",
    privacy_s1_body: "Мы используем Google Analytics и Google Tag Manager (GTM) для сбора анонимной статистики о посещениях сайта. Это помогает нам понимать, как пользователи взаимодействуют с сервисом, и улучшать его. Собираемые данные включают: страницы посещений, время на сайте, тип устройства, географическое расположение (на уровне страны) и источник перехода.",
    privacy_s2_title: "2. Реклама",
    privacy_s2_body: "Мы используем Google AdSense для показа рекламы на сайте. AdSense может использовать файлы cookie для показа персонализированной рекламы на основе ваших предыдущих посещений нашего и других сайтов. Вы можете отказаться от персонализированной рекламы в настройках рекламы Google.",
    privacy_s3_title: "3. Сбор электронной почты",
    privacy_s3_body: "Если вы подписываетесь на нашу рассылку, мы сохраняем ваш адрес электронной почты для отправки обновлений о новых функциях, изменениях тарифов и полезных руководствах по доставке. Вы можете отписаться в любое время, перейдя по ссылке в нижней части любого письма.",
    privacy_s4_title: "4. Локальное хранилище",
    privacy_s4_body: "Мы используем localStorage в вашем браузере для сохранения избранных маршрутов доставки и пользовательских настроек (валюта, единицы веса). Эти данные хранятся только на вашем устройстве и не передаются на наши серверы.",
    privacy_s5_title: "5. Файлы cookie",
    privacy_s5_body: "Наш сайт использует файлы cookie для работы Google Analytics, Google Tag Manager и Google AdSense. Эти cookie помогают анализировать трафик и показывать релевантную рекламу. Вы можете управлять cookie в настройках вашего браузера.",
