    disclaimer_body: "Окончательный размер пошлины определяет таможня страны назначения при оформлении и может отличаться из-за досмотра, метода оценки или документов о происхождении. Наши цифры стремятся к тому, что вы реально заплатите, — но это не юридическая или таможенная консультация. Для отправлений дороже $25 000 или товаров под регулированием обращайтесь к лицензированному таможенному брокеру.",
