    duty_faq_2_q: "Как часто обновляются данные?",
    duty_faq_2_a: "Еженедельно. Крупные изменения тарифов (например, новые санкции США/ЕС) подтягиваются вне расписания, но штатный режим — еженедельное обновление из официальных фидов каждого ведомства.",
    duty_faq_3_q: "Учитывает ли калькулятор торговые соглашения?",
    duty_faq_3_a: "Для крупных соглашений (USMCA, EU-UK TCA, CPTPP, Mercosur) мы применяем преференциальную ставку в профиле страны, если ваше происхождение под неё подходит. Документы о правилах происхождения — на вашей стороне; мы не выдаём сертификаты происхождения.",
    duty_faq_4_q: "А если таможня насчитает не так, как у вас?",
    duty_faq_4_a: "Окончательное решение всегда за таможней. Наша цифра — добросовестная оценка по официальной тарифной сетке. Расхождения чаще всего связаны с методом оценки, спорной HS-классификацией или непредвиденными регуляторными моментами (лицензии, ограниченные товары). Для отправлений дороже $25 000 или регулируемых категорий используйте лицензированного брокера.",
    duty_faq_5_q: "Работаете ли вы с регулируемыми товарами?",
