    stat_free_v: "Gratis",
    stat_free_l: "Para siempre · sin registro",
    disclaimer_eyebrow: "Estimación de buena fe, no una determinación vinculante",
    disclaimer_body: "El arancel final lo determina la autoridad aduanera de destino en el momento del despacho y puede variar según la inspección, el método de valoración o la documentación de origen. Nuestras cifras buscan acercarse a lo que pagarás realmente, pero esto no es asesoramiento legal ni aduanero. Para envíos superiores a 25.000 $ o mercancías reguladas, consulta a un agente de aduanas autorizado.",
    faq_eyebrow: "Preguntas que recibimos cada semana",
    duty_faq_1_q: "¿De dónde salen vuestros tipos arancelarios?",
    duty_faq_1_a: "Directamente del arancel publicado de cada país: el HTSUS de EE. UU., la base TARIC de la UE, el UK Integrated Online Tariff, el arancel del CBSA de Canadá y equivalentes para el resto de mercados. No hacemos scraping de los motores de presupuestos de los transportistas.",
    duty_faq_2_q: "¿Con qué frecuencia se actualizan los datos?",
    duty_faq_2_a: "Semanalmente. Los cambios arancelarios importantes (por ejemplo, nuevas sanciones de EE. UU. o la UE) se incorporan fuera del calendario habitual, pero la cadencia normal es una actualización semanal a partir del feed publicado por cada autoridad.",
    duty_faq_3_q: "¿La calculadora tiene en cuenta los acuerdos comerciales?",
    duty_faq_3_a: "Para los grandes acuerdos (T-MEC, TCA UE-Reino Unido, CPTPP, Mercosur) aplicamos el tipo preferencial en el perfil de país en el que tu origen reúne los requisitos. La documentación de origen es responsabilidad tuya: nosotros no generamos certificados de origen.",
    duty_faq_4_q: "¿Y si la autoridad aduanera cobra algo distinto a vuestra estimación?",
    duty_faq_4_a: "La liquidación final siempre la decide la autoridad aduanera. Nuestra cifra es una estimación de buena fe basada en el arancel publicado. Las diferencias suelen venir del método de valoración, de discrepancias en la clasificación HS o de hallazgos regulatorios inesperados (licencias, mercancías restringidas). Para envíos superiores a 25.000 $ o categorías reguladas, usa un agente autorizado.",
    duty_faq_5_q: "¿Gestionáis mercancías reguladas?",
    duty_faq_5_a: "Marcamos las restricciones generales para baterías de litio, cosméticos, alcohol, productos farmacéuticos y otras categorías reguladas en los perfiles de país. Las licencias y permisos reales se gestionan fuera de la calculadora, normalmente a través de un agente de aduanas en el país de destino.",
    duty_faq_6_q: "¿La calculadora es realmente gratis?",
    duty_faq_6_a: "Sí. Sin registro, sin muro de pago, sin límite de consultas. Somos un equipo pequeño en Hungría (Global Supply KFT) y la calculadora seguirá siendo gratuita.",
    duty_cta_pre: "Tus clientes no deberían enterarse de los aranceles en su",
    duty_cta_accent: "puerta.",
    duty_cta_desc: "Estima el precio total antes de enviar. Sin registro. Sin pagos. Sin facturas sorpresa cuando el paquete pase por aduana.",
