    feat_dm_body: "800 USD US · 150 EUR EU · 135 GBP UK · 40 CAD · 1.000 AUD. Wir verfolgen den Schwellenwert und die Bedingungen – Ihre Sendung qualifiziert sich erst, wenn das gesamte Regelwerk erfüllt ist.",
