    feat_honest_tag: "Keine Anmeldung, kein Upselling",
    feat_honest_body: "Der Rechner ist und bleibt kostenlos. Da wir keine Carrier-Provisionen erhalten, ist die Antwort, die wir Ihnen geben, die, die unsere Daten tatsächlich liefern – nicht die, die uns am meisten einbringt.",
