    duty_hero_desc: "Kosten frei Haus in Sekunden. Zoll, Mehrwertsteuer/GST, Verzollungsgebühren, De-minimis-Schwellenwerte – angewendet auf Ihr Bestimmungsland und den deklarierten Wert, für jedes von uns abgedeckte Gebiet.",
