    disclaimer_eyebrow: "Schätzung nach bestem Wissen – keine verbindliche Festsetzung",
    disclaimer_body: "Der endgültige Zoll wird von der Zollbehörde des Bestimmungslandes zum Zeitpunkt der Verzollung festgesetzt und kann je nach Inspektion, Bewertungsmethode oder Ursprungsdokumentation abweichen. Unsere Zahlen zielen darauf ab, dem tatsächlich zu zahlenden Betrag nahezukommen – sie stellen jedoch keine Rechts- oder Zollberatung dar. Für Sendungen über 25.000 USD oder regulierte Waren konsultieren Sie bitte einen lizenzierten Zollagenten.",
    faq_eyebrow: "Fragen, die uns wöchentlich erreichen",
    duty_faq_1_q: "Woher stammen Ihre Zollsätze?",
    duty_faq_1_a: "Direkt aus dem veröffentlichten Tarifverzeichnis jedes Landes – dem US-HTSUS, der EU-TARIC-Datenbank, dem UK Integrated Online Tariff, dem kanadischen CBSA-Tarif und entsprechenden Quellen für alle anderen Märkte. Wir scrapen keine Carrier-Angebotsmaschinen.",
    duty_faq_2_q: "Wie oft werden die Daten aktualisiert?",
    duty_faq_2_a: "Wöchentlich. Größere Tarifänderungen (z. B. neue US-/EU-Sanktionen) werden außer der Reihe übernommen, der normale Rhythmus ist jedoch eine wöchentliche Aktualisierung aus dem veröffentlichten Feed jeder Behörde.",
    duty_faq_3_q: "Berücksichtigt der Rechner Handelsabkommen?",
    duty_faq_3_a: "Für die wichtigsten Abkommen (USMCA, EU-UK TCA, CPTPP, Mercosur) wenden wir den Präferenzsatz im Länderprofil an, wenn Ihr Ursprung qualifiziert ist. Die Ursprungsregel-Dokumentation liegt in Ihrer Verantwortung – wir stellen keine Ursprungszeugnisse aus.",
    duty_faq_4_q: "Was ist, wenn die Zollbehörde etwas anderes berechnet als Ihre Schätzung?",
    duty_faq_4_a: "Die endgültige Festsetzung obliegt immer der Zollbehörde. Unsere Zahl ist eine Schätzung nach bestem Wissen auf Basis des veröffentlichten Tarifverzeichnisses. Abweichungen entstehen am häufigsten durch die Bewertungsmethode, Streitigkeiten zur HS-Klassifizierung oder unerwartete regulatorische Befunde (Lizenzen, eingeschränkte Waren). Für Sendungen über 25.000 USD oder regulierte Kategorien nutzen Sie bitte einen lizenzierten Zollagenten.",
    duty_faq_5_q: "Behandeln Sie regulierte Waren?",
    duty_faq_5_a: "Wir kennzeichnen allgemeine Beschränkungen für Lithiumbatterien, Kosmetika, Alkohol, Pharmazeutika und andere regulierte Kategorien in den Länderprofilen. Tatsächliche Lizenzen und Genehmigungen werden außerhalb des Rechners abgewickelt – typischerweise über einen Zollagenten im Bestimmungsland.",
    duty_faq_6_q: "Ist der Rechner wirklich kostenlos?",
    duty_faq_6_a: "Ja. Keine Anmeldung, keine Bezahlschranke, keine Begrenzung der Abfragen. Wir sind ein kleines Team in Ungarn (Global Supply KFT) und der Rechner bleibt kostenlos.",
    duty_cta_pre: "Ihre Kunden sollten nicht erst an ihrer",
