    feat_honest_tag: "Sans inscription, sans vente additionnelle",
    feat_honest_body: "Le calculateur est gratuit et le restera. L'absence de commissions des transporteurs signifie que la réponse que nous donnons est celle que les données disent réellement — pas celle qui nous rapporte le plus.",
