    disclaimer_eyebrow: "Estimation de bonne foi — pas une décision contraignante",
    disclaimer_body: "Les droits définitifs sont évalués par l'autorité douanière de destination au moment du dédouanement et peuvent varier selon l'inspection, la méthode de valorisation ou les documents d'origine. Nos chiffres visent à être proches de ce que vous paierez réellement — mais ceci n'est pas un conseil juridique ou douanier. Pour les envois de plus de 25 000 $ ou les marchandises réglementées, consultez un courtier en douane agréé.",
    faq_eyebrow: "Questions fréquentes chaque semaine",
    duty_faq_1_q: "D'où viennent vos taux de douane ?",
    duty_faq_1_a: "Directement des grilles tarifaires publiées de chaque pays — HTSUS américain, base TARIC de l'UE, UK Integrated Online Tariff, tarif CBSA du Canada, et équivalents pour tous les autres marchés. Nous ne scrapons pas les moteurs de devis des transporteurs.",
    duty_faq_2_q: "À quelle fréquence les données sont-elles mises à jour ?",
    duty_faq_2_a: "Chaque semaine. Les changements tarifaires majeurs (par exemple nouvelles sanctions US/UE) sont intégrés hors cycle, mais la cadence normale est une actualisation hebdomadaire depuis le flux publié de chaque autorité.",
    duty_faq_3_q: "Le calculateur tient-il compte des accords commerciaux ?",
    duty_faq_3_a: "Pour les principaux accords (USMCA, ACEUM-RU, CPTPP, Mercosur), nous appliquons le taux préférentiel dans le profil pays lorsque votre origine y est éligible. La documentation sur les règles d'origine relève de votre responsabilité — nous ne générons pas de certificats d'origine.",
    duty_faq_4_q: "Et si la douane facture un montant différent de votre estimation ?",
    duty_faq_4_a: "L'évaluation finale appartient toujours à l'autorité douanière. Notre chiffre est une estimation de bonne foi basée sur la grille tarifaire publiée. Les écarts proviennent le plus souvent de la méthode de valorisation, de litiges sur le classement SH, ou de constats réglementaires inattendus (licences, marchandises restreintes). Pour les envois de plus de 25 000 $ ou les catégories réglementées, utilisez un courtier agréé.",
    duty_faq_5_q: "Gérez-vous les marchandises réglementées ?",
    duty_faq_5_a: "Nous signalons les restrictions générales sur les batteries au lithium, les cosmétiques, l'alcool, les produits pharmaceutiques et autres catégories réglementées dans les profils pays. Les licences et permis effectifs sont gérés en dehors du calculateur — généralement via un courtier en douane du pays de destination.",
    duty_faq_6_q: "Le calculateur est-il vraiment gratuit ?",
    duty_faq_6_a: "Oui. Sans inscription, sans paywall, sans limite de requêtes. Nous sommes une petite équipe en Hongrie (Global Supply KFT) et le calculateur restera gratuit.",
    duty_cta_pre: "Vos clients ne devraient pas découvrir la douane à leur",
    duty_cta_accent: "porte d'entrée.",
    duty_cta_desc: "Estimez le prix tout compris avant l'expédition. Sans inscription. Sans paiement. Sans facture surprise au dédouanement.",
