    stat_free_v: "Gratuito",
    stat_free_l: "Para sempre · sem registo",
    disclaimer_eyebrow: "Estimativa de boa-fé — não uma determinação vinculativa",
    disclaimer_body: "Os direitos finais são determinados pela autoridade aduaneira do destino no momento do desalfandegamento e podem diferir consoante a inspecção, o método de avaliação ou a documentação de origem. Os nossos números pretendem aproximar-se do que irá realmente pagar — mas isto não constitui aconselhamento jurídico nem aduaneiro. Para envios acima de 25.000 USD ou mercadorias regulamentadas, consulte um despachante oficial licenciado.",
    faq_eyebrow: "Perguntas que recebemos semanalmente",
    duty_faq_1_q: "De onde vêm as vossas taxas de direitos?",
    duty_faq_1_a: "Directamente da pauta aduaneira publicada de cada país — o HTSUS dos EUA, a base de dados TARIC da UE, o UK Integrated Online Tariff, a pauta da CBSA do Canadá, e equivalentes para todos os outros mercados. Não fazemos scraping a motores de orçamento de transportadoras.",
    duty_faq_2_q: "Com que frequência os dados são actualizados?",
    duty_faq_2_a: "Semanalmente. Alterações tarifárias importantes (por exemplo, novas sanções dos EUA/UE) são incorporadas fora do ciclo, mas a cadência normal é uma actualização semanal a partir do feed publicado de cada autoridade.",
    duty_faq_3_q: "A calculadora considera os acordos comerciais?",
    duty_faq_3_a: "Para os principais acordos (USMCA, TCA UE-Reino Unido, CPTPP, Mercosul) aplicamos a taxa preferencial no perfil de país onde a sua origem se qualifica. A documentação de regras de origem é da sua responsabilidade — não emitimos certificados de origem.",
    duty_faq_4_q: "E se a autoridade aduaneira cobrar algo diferente da vossa estimativa?",
    duty_faq_4_a: "A determinação final é sempre da autoridade aduaneira. O nosso valor é uma estimativa de boa-fé baseada na pauta aduaneira publicada. As diferenças surgem mais frequentemente do método de avaliação, disputas de classificação HS ou conclusões regulatórias inesperadas (licenciamento, mercadorias restritas). Para envios acima de 25.000 USD ou categorias regulamentadas, utilize um despachante licenciado.",
    duty_faq_5_q: "Tratam de mercadorias regulamentadas?",
    duty_faq_5_a: "Sinalizamos restrições gerais para baterias de lítio, cosméticos, álcool, produtos farmacêuticos e outras categorias regulamentadas nos perfis de países. O licenciamento e as autorizações efectivas são tratados fora da calculadora — normalmente através de um despachante no país de destino.",
    duty_faq_6_q: "A calculadora é mesmo gratuita?",
    duty_faq_6_a: "Sim. Sem registo, sem paywall, sem limite de pesquisas. Somos uma equipa pequena na Hungria (Global Supply KFT) e a calculadora vai continuar a ser gratuita.",
    duty_cta_pre: "Os seus clientes não devem aprender sobre alfândegas à",
