    disclaimer_body: "최종 관세는 통관 시점에 도착지 세관 당국이 부과하며, 검사, 평가 방법 또는 원산지 서류에 따라 달라질 수 있습니다. 당사 수치는 실제 납부 금액에 가깝게 산출하는 것을 목표로 하지만, 법률 또는 통관 자문이 아닙니다. $25,000을 초과하는 화물이나 규제 품목의 경우 공인 관세사와 상담하시기 바랍니다.",
    faq_eyebrow: "매주 받는 질문들",
    duty_faq_1_q: "관세율은 어디에서 가져옵니까?",
    duty_faq_1_a: "각국의 공시 관세 일정에서 직접 가져옵니다 — 미국 HTSUS, EU TARIC 데이터베이스, UK Integrated Online Tariff, 캐나다 CBSA 관세, 그리고 다른 모든 시장의 동등 자료입니다. 운송사 견적 엔진을 스크래핑하지 않습니다.",
    duty_faq_2_q: "데이터는 얼마나 자주 업데이트됩니까?",
    duty_faq_2_a: "매주입니다. 주요 관세 변경(예: 신규 미국/EU 제재)은 별도 경로로 즉시 반영하지만, 일반 주기는 각 기관의 공시 피드에서 매주 갱신하는 방식입니다.",
    duty_faq_3_q: "계산기는 무역 협정을 반영합니까?",
    duty_faq_3_a: "주요 협정(USMCA, EU-UK TCA, CPTPP, Mercosur)의 경우, 출발지가 자격을 갖춘 국가 프로필에 특혜 세율을 적용해 드립니다. 원산지 규정 서류는 고객의 책임이며 — 당사는 원산지 증명서를 발급하지 않습니다.",
    duty_faq_4_q: "세관 당국이 추정치와 다른 금액을 부과하면 어떻게 됩니까?",
    duty_faq_4_a: "최종 평가는 항상 세관 당국의 권한입니다. 당사 수치는 공시 관세 일정에 기반한 선의의 추정치입니다. 차이는 주로 평가 방법, HS 분류 분쟁, 또는 예상치 못한 규제 사항(라이선스, 제한 품목)에서 발생합니다. $25,000을 초과하는 화물이나 규제 카테고리의 경우 공인 관세사를 이용해 주십시오.",
    duty_faq_5_q: "규제 품목도 다룹니까?",
    duty_faq_5_a: "리튬 배터리, 화장품, 주류, 의약품 및 기타 규제 카테고리에 대한 일반 제한 사항을 국가 프로필에 표시합니다. 실제 라이선스와 허가는 계산기 외부에서 처리되며 — 일반적으로 도착 국가의 관세사를 통해 진행합니다.",
    duty_faq_6_q: "계산기는 정말로 무료입니까?",
    duty_faq_6_a: "예. 가입도, 유료 장벽도, 조회 횟수 제한도 없습니다. 당사는 헝가리에 위치한 소규모 팀(Global Supply KFT)이며, 계산기는 앞으로도 무료로 제공됩니다.",
