    disclaimer_body: "تُحدَّد الرسوم النهائية من قِبَل سلطة الجمارك في بلد الوجهة وقت التخليص، وقد تختلف بناءً على المعاينة، أو طريقة التقييم، أو وثائق المنشأ. تهدف أرقامنا إلى أن تكون قريبة ممّا ستدفعه فعلًا — لكنها ليست استشارة قانونية أو جمركية. للشحنات التي تتجاوز قيمتها 25,000 دولار أو السلع المنظّمة، استشِر مخلّصًا جمركيًا مرخّصًا.",
