    duty_faq_1_a: "مباشرة من جدول التعرفات المنشور لكل دولة — HTSUS الأمريكي، وقاعدة بيانات TARIC الأوروبية، وUK Integrated Online Tariff البريطانية، وتعرفة CBSA الكندية، ومثيلاتها لجميع الأسواق الأخرى. نحن لا نُجرّف محرّكات عروض الأسعار لدى شركات الشحن.",
    duty_faq_2_q: "كم مرّة تُحدَّث البيانات؟",
    duty_faq_2_a: "أسبوعيًا. التغييرات الكبرى في التعرفات (مثل العقوبات الأمريكية/الأوروبية الجديدة) تُسحَب خارج الجدول المعتاد، لكن الوتيرة الطبيعية هي تحديث أسبوعي من قناة كل جهة جمركية.",
    duty_faq_3_q: "هل تأخذ الحاسبة في الحسبان اتفاقيات التجارة؟",
    duty_faq_3_a: "بالنسبة للاتفاقيات الكبرى (USMCA، EU-UK TCA، CPTPP، Mercosur) نُطبّق السعر التفضيلي في ملف الدولة عندما يستوفي بلد المنشأ لديك الشروط. توثيق قواعد المنشأ مسؤوليتك أنت — نحن لا نُصدِر شهادات منشأ.",
    duty_faq_4_q: "ماذا لو فرضت سلطة الجمارك مبلغًا مختلفًا عن تقديركم؟",
    duty_faq_4_a: "القرار النهائي دائمًا بيد سلطة الجمارك. رقمنا تقدير بحُسن نيّة مبني على جدول التعرفات المنشور. تنشأ الفروقات في الغالب من طريقة التقييم، أو الخلاف على تصنيف رمز HS، أو نتائج تنظيمية غير متوقّعة (التراخيص، السلع المُقيَّدة). للشحنات التي تتجاوز 25,000 دولار أو الفئات المنظّمة، يُرجى استخدام مخلّص جمركي مرخّص.",
    duty_faq_5_q: "هل تتعاملون مع السلع المنظّمة؟",
    duty_faq_5_a: "نُشير إلى القيود العامّة على بطاريات الليثيوم، ومستحضرات التجميل، والكحول، والمستحضرات الصيدلانية، وغيرها من الفئات المنظّمة في ملفات الدول. أمّا التراخيص والتصاريح الفعلية فتُعالَج خارج الحاسبة — عادةً عبر مخلّص جمركي في بلد الوجهة.",
    duty_faq_6_q: "هل الحاسبة مجانية فعلًا؟",
