    disclaimer_body: "Nihai gümrük vergisi, gümrükleme sırasında varış ülkesi gümrük yetkilisi tarafından değerlendirilir ve inceleme, değer tespit yöntemi veya menşe belgelerine bağlı olarak farklılık gösterebilir. Rakamlarımız gerçekten ödeyeceğinize yakın olmayı amaçlar — ancak bu yasal veya gümrük tavsiyesi değildir. $25.000 üzerindeki gönderiler veya düzenlemeye tabi mallar için lisanslı bir gümrük müşaviriyle görüşün.",
