    duty_faq_2_q: "Veriler ne sıklıkla güncelleniyor?",
    duty_faq_2_a: "Haftalık. Büyük tarife değişiklikleri (örn. yeni ABD/AB yaptırımları) bant dışı olarak çekilir, ancak normal sıklık her yetkilinin yayınlanmış akışından haftalık yenilemedir.",
    duty_faq_3_q: "Hesaplayıcı ticaret anlaşmalarını dikkate alıyor mu?",
    duty_faq_3_a: "Büyük anlaşmalar için (USMCA, EU-UK TCA, CPTPP, Mercosur) menşeinizin uygun olduğu ülke profilinde tercihli oranı uygularız. Menşe kuralı belgelendirmesi sizin sorumluluğunuzdadır — menşe sertifikaları üretmiyoruz.",
    duty_faq_4_q: "Gümrük yetkilisi tahmininizden farklı bir ücret alırsa ne olur?",
    duty_faq_4_a: "Nihai değerlendirme her zaman gümrük yetkilisine aittir. Rakamımız, yayınlanmış tarife cetveline dayalı iyi niyetli bir tahmindir. Farklılıklar genellikle değer tespit yöntemi, HS sınıflandırma anlaşmazlıkları veya beklenmedik düzenleyici bulgulardan (lisanslama, kısıtlanmış mallar) kaynaklanır. $25.000 üzerindeki gönderiler veya düzenlemeye tabi kategoriler için lütfen lisanslı bir müşavir kullanın.",
    duty_faq_5_q: "Düzenlemeye tabi mallarla ilgileniyor musunuz?",
    duty_faq_5_a: "Lityum piller, kozmetik, alkol, ilaç ve diğer düzenlemeye tabi kategoriler için genel kısıtlamaları ülke profillerinde işaretliyoruz. Gerçek lisanslama ve izinler hesaplayıcı dışında — genellikle varış ülkesi gümrük müşaviri aracılığıyla — yönetilir.",
    duty_faq_6_q: "Hesaplayıcı gerçekten ücretsiz mi?",
