export type DictKey = string;

export function t(locale: Locale, key: string, params?: Record<string, string | number>): string {
  let text = dictionaries[locale]?.[key] ?? dictionaries.en[key] ?? key;
  if (params) {
    for (const [k, v] of Object.entries(params)) {
      text = text.replace(`{${k}}`, String(v));
    }
  }
  return text;
}

export function tf(locale: Locale, key: string, fallback: string, params?: Record<string, string | number>): string {
  let text = dictionaries[locale]?.[key] ?? dictionaries.en[key] ?? fallback;
  if (params) {
    for (const [k, v] of Object.entries(params)) {
      text = text.replace(`{${k}}`, String(v));
    }
  }
  return text;
}

/**
 * Pick a localized field from an object that has `<field>_<locale>` suffixes.
 * Falls back in order: requested locale -> English -> first non-empty -> "".
 * Example: pickLocalized(post, "title", "ja") reads post.title_ja ?? post.title_en.
 */
export function pickLocalized<T extends Record<string, unknown>>(
  obj: T,
  field: string,
  locale: Locale,
): string {
  const requested = obj[`${field}_${locale}`];
  if (typeof requested === "string" && requested.length > 0) return requested;
  const english = obj[`${field}_en`];
  if (typeof english === "string" && english.length > 0) return english;
  for (const l of locales) {
    const v = obj[`${field}_${l}`];
    if (typeof v === "string" && v.length > 0) return v;
  }
  return "";
}
